L45_1 = "지난번에는 밤하늘에 빛나는 별에 닿을 것처럼 하늘로 치솟았는데 말이지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "この前は夜空に光る星に届くくらい空高く飛んだのに。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Last time, we blasted off like we were about to grab the stars."
L44_1.m_Talk_ENG = L45_1
L45_1 = "上次就像要觸碰到夜空中閃耀的星星一樣衝向天空。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "上次就像要触碰到夜空中闪耀的星星一样冲向了天空。"
