L45_1.m_Pos = "R"
L46_1 = "이번에는 멀쩡한 맨땅에다 다이빙하게 생겼잖냐? 대체 우리 인생은 왜 이런 거냐?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "今度は地面にダイブするんだろ？　私たちの人生っていったいどうなってるんだ？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "This time, we're face-planting into a pile of dirt. Why are our lives so messed up?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "這次又要在平地上躍入？我們的生活到底為什麼是這樣？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "这次又要在平地上跃入了？我们的生活到底为什么会这样？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "This time, we're face-planting into a pile of dirt. Why are our lives so messed up?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "This time, we're face-planting into a pile of dirt. Why are our lives so messed up?"
